fig,axis=plt.subplots(figsize=(3.5,3.15))
axes=[axis]
report=[]
for ax,group in zip(axes,[['est5', 'est1', 'est_only', 'dem_only', 'joint', 'joint_pretrain10', 'cnn']]):
 for method in group:
  label,color,marker,ls=styles[method]
  data=[sorted([r for r in rows if r['method']==method and int(r['seed'])==seed],key=lambda r:int(r['iteration'])) for seed in [42,43,44]]
  assert len({len(d) for d in data})==1
  yy=np.array([[float(r['ber']) for r in rr] for rr in data]);xx=np.array([[float(r['seconds']) for r in rr] for rr in data]);x=xx.mean(axis=0)
  mask=(x>0)&(x<=10)
  t=x[mask];y=yy[:,mask]
  markers=sorted(set(int(np.argmin(np.abs(np.log(t)-np.log(v)))) for v in np.geomspace(t[0],t[-1],7)))
